<template><div class="student-page"><header class="heading"><button v-if="courseName" type="button" class="back" @click="router.back()">← 返回课程</button><div><p>COURSE SCORES</p><h1>{{ courseName ? `${courseName} · 成绩` : '我的成绩' }}</h1><span>查看已发布的个人成绩和团队贡献</span></div></header><div v-if="errorMessage" class="error">{{ errorMessage }}</div><section class="panel"><div class="panel-head"><h2>成绩记录</h2><span>{{ visibleScores.length }} 条</span></div><div v-for="item in visibleScores" :key="item.scoreResultId" class="score-row"><div><strong>{{ item.assignmentTitle }}</strong><small>{{ item.courseName }} · {{ item.groupName || '未分组' }}</small></div><div><span>贡献 {{ ratio(item.contribution) }}</span><b>{{ item.finalScore == null ? '未发布' : Number(item.finalScore).toFixed(2) }}</b></div></div><el-empty v-if="!visibleScores.length" description="该课程暂无已发布成绩" /></section></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElEmpty } from 'element-plus';import { getScores } from '@/api/student';import { getErrorMessage } from '@/api/response';const route=useRoute(),router=useRouter(),scores=ref([]),errorMessage=ref('');const courseName=computed(()=>String(route.query.courseName||''));const visibleScores=computed(()=>courseName.value?scores.value.filter(item=>item.courseName===courseName.value):scores.value);const ratio=v=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;onMounted(async()=>{try{scores.value=await getScores()}catch(e){errorMessage.value=getErrorMessage(e,'成绩加载失败')}})
</script>
<style scoped>.student-page{max-width:1180px;margin:0 auto}.heading{margin-bottom:27px;padding:4px 2px}.back{margin-bottom:17px;padding:0;border:0;color:#4f86c6;background:none;cursor:pointer}.heading p{margin:0 0 7px;color:#4f86c6;font-size:11px;font-weight:700;letter-spacing:1.6px}.heading h1{margin:0 0 8px;color:#22364d;font-size:30px}.heading span{color:#7c8da0}.panel{overflow:hidden;border:1px solid #e3eaf2;border-radius:13px;background:#fff;box-shadow:0 5px 18px rgba(38,59,83,.06)}.panel-head{display:flex;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #e9eef5;background:#fbfdff}.panel-head h2{margin:0;color:#263b53;font-size:17px}.panel-head span{color:#4f86c6;font-size:13px}.score-row{display:flex;align-items:center;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #edf1f5;transition:background .2s}.score-row:hover{background:#f8fbff}.score-row:last-child{border-bottom:0}.score-row strong,.score-row small{display:block}.score-row strong{color:#334155}.score-row small{margin-top:6px;color:#94a3b8;font-size:12px}.score-row div:last-child{display:grid;gap:5px;text-align:right;color:#7c8da0;font-size:12px}.score-row b{color:#356798;font-size:23px}.error{margin-bottom:16px;padding:14px;border-radius:9px;color:#b42318;background:#fff5f5}@media(max-width:600px){.heading h1{font-size:25px}.score-row{padding:16px}.score-row b{font-size:20px}}</style>
